import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const c=JSON.parse('{"title":"Roadmaps — Advanced Features & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"roadmaps-03-advanced-and-customization.md","filePath":"roadmaps-03-advanced-and-customization.md"}'),i={name:"roadmaps-03-advanced-and-customization.md"};function n(s,e,l,d,h,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="roadmaps-—-advanced-features-customization" tabindex="-1">Roadmaps — Advanced Features &amp; Customization <a class="header-anchor" href="#roadmaps-—-advanced-features-customization" aria-label="Permalink to &quot;Roadmaps — Advanced Features &amp; Customization&quot;">​</a></h1><p><em>Contextual visualization, hierarchy design, and getting the most from Roadmap exports</em></p><hr><h2 id="designing-your-hierarchy" tabindex="-1">Designing Your Hierarchy <a class="header-anchor" href="#designing-your-hierarchy" aria-label="Permalink to &quot;Designing Your Hierarchy&quot;">​</a></h2><p>The sunburst has no enforced structure — you define what each ring means. This flexibility is powerful but can feel overwhelming at first. Here are the most common patterns to draw from:</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Ring 1 (center)</th><th>Ring 2</th><th>Ring 3 (outer)</th></tr></thead><tbody><tr><td>Strategic</td><td>Goals</td><td>Themes</td><td>Features</td></tr><tr><td>Lifecycle</td><td>Lifecycle Stage</td><td>Objective</td><td>Feature</td></tr><tr><td>Customer-centric</td><td>Persona</td><td>Job to be Done</td><td>Feature</td></tr><tr><td>Simple</td><td>Theme</td><td>Feature</td><td>—</td></tr></tbody></table><p>There is no &quot;right&quot; answer. The best hierarchy is the one that makes your plan immediately legible to your specific audience. For a board presentation, a two-level Goals → Features structure may be all you need. For an engineering alignment session, a three-level breakdown may be more useful.</p><h3 id="practical-guidance" tabindex="-1">Practical guidance <a class="header-anchor" href="#practical-guidance" aria-label="Permalink to &quot;Practical guidance&quot;">​</a></h3><ul><li><strong>Start with your audience</strong> — what story are you trying to tell, and what groupings will make sense to them?</li><li><strong>Fewer levels is usually better</strong> — three levels is a common sweet spot; more than four can make the sunburst hard to read</li><li><strong>Be consistent</strong> — if Ring 2 means &quot;Theme&quot; in one section of the roadmap, it should mean &quot;Theme&quot; everywhere</li></ul><hr><h2 id="using-multiple-roadmaps" tabindex="-1">Using Multiple Roadmaps <a class="header-anchor" href="#using-multiple-roadmaps" aria-label="Permalink to &quot;Using Multiple Roadmaps&quot;">​</a></h2><p>Because a workspace can have multiple Roadmaps, and the same Feature can appear in more than one, you can maintain different Roadmap views for different audiences or time horizons simultaneously.</p><p>Common patterns:</p><ul><li><strong>Annual + Quarterly</strong> — a high-level annual roadmap showing strategic direction, and a quarterly roadmap with more tactical detail</li><li><strong>By audience</strong> — one roadmap structured for executive alignment (Goals → Features), another for engineering (Themes → Epics → Features)</li><li><strong>By product area</strong> — separate roadmaps for different product lines or teams</li></ul><p>Because Features are shared objects, updates to a Feature (name, status, description) are reflected in every Roadmap it appears in — there&#39;s no duplication to maintain.</p><hr><h2 id="contextual-visualization-in-depth" tabindex="-1">Contextual Visualization in Depth <a class="header-anchor" href="#contextual-visualization-in-depth" aria-label="Permalink to &quot;Contextual Visualization in Depth&quot;">​</a></h2><p>Contextual sizing and coloring add an analytical layer on top of the structural hierarchy. Used well, they can turn a roadmap into a prioritization argument — not just a list of what you&#39;re building, but a visual case for why these things and not others.</p><h3 id="sizing-by-value-vs-effort" tabindex="-1">Sizing by Value vs Effort <a class="header-anchor" href="#sizing-by-value-vs-effort" aria-label="Permalink to &quot;Sizing by Value vs Effort&quot;">​</a></h3><ul><li><strong>Size by Value</strong> — larger segments represent higher-value Features. This draws the eye to your most impactful work and makes it visually obvious where the biggest bets are.</li><li><strong>Size by Effort</strong> — larger segments represent higher-effort Features. This is useful for surfacing where resources are concentrated and whether the effort allocation matches the value.</li></ul><h3 id="coloring-by-value-vs-effort" tabindex="-1">Coloring by Value vs Effort <a class="header-anchor" href="#coloring-by-value-vs-effort" aria-label="Permalink to &quot;Coloring by Value vs Effort&quot;">​</a></h3><p>The default color scale runs green (Extra Small) → red (Extra Large), but every level is customizable. Consider:</p><ul><li><strong>Green = high, red = low</strong> for value — reinforces positive framing of high-value work</li><li><strong>Green = low, red = high</strong> for effort — flags where the heavy lifts are</li></ul><h3 id="combining-both" tabindex="-1">Combining both <a class="header-anchor" href="#combining-both" aria-label="Permalink to &quot;Combining both&quot;">​</a></h3><p>The most expressive configuration uses both simultaneously:</p><ul><li><strong>Size by Value, Color by Effort</strong> — large green segments are high value, low effort (the sweet spots); small red segments are low value, high effort (the ones to question)</li></ul><p>This combination lets you make a prioritization argument visually without saying a word.</p><blockquote><p><strong>Reminder:</strong> Contextual visualization only affects the outermost ring. Hierarchy color families on parent and grandparent items remain unchanged.</p></blockquote><hr><h2 id="telling-the-story-of-deprioritization" tabindex="-1">Telling the Story of Deprioritization <a class="header-anchor" href="#telling-the-story-of-deprioritization" aria-label="Permalink to &quot;Telling the Story of Deprioritization&quot;">​</a></h2><p>One of the most underused Roadmap practices is keeping deprioritized items visible. Rather than deleting Features that didn&#39;t make the cut, move them into a clearly labelled &quot;Not Now&quot; or &quot;Deprioritized&quot; section at the bottom of the Roadmap.</p><p>This does several things:</p><ul><li>Shows stakeholders that their ideas were considered, not ignored</li><li>Makes the tradeoff explicit — here&#39;s what we chose, and here&#39;s what we didn&#39;t</li><li>Gives you a ready-made list to revisit in the next planning cycle</li></ul><p>A roadmap that only shows what you&#39;re building is half a story. A roadmap that also shows what you&#39;re not building — and implicitly why — is a full one.</p><hr><h2 id="getting-the-most-from-the-full-ppt-export" tabindex="-1">Getting the Most from the Full PPT Export <a class="header-anchor" href="#getting-the-most-from-the-full-ppt-export" aria-label="Permalink to &quot;Getting the Most from the Full PPT Export&quot;">​</a></h2><p>The full PPT presentation export is Lodestone&#39;s most powerful communication artifact. A few tips for getting the best output:</p><h3 id="build-your-hierarchy-with-the-export-in-mind" tabindex="-1">Build your hierarchy with the export in mind <a class="header-anchor" href="#build-your-hierarchy-with-the-export-in-mind" aria-label="Permalink to &quot;Build your hierarchy with the export in mind&quot;">​</a></h3><p>Because every item at every level gets its own slide, the names you give to your items become slide titles. Treat them as headlines — specific enough to be meaningful, concise enough to read at a glance.</p><h3 id="generate-opportunity-canvases-before-exporting" tabindex="-1">Generate Opportunity Canvases before exporting <a class="header-anchor" href="#generate-opportunity-canvases-before-exporting" aria-label="Permalink to &quot;Generate Opportunity Canvases before exporting&quot;">​</a></h3><p>Opportunity Canvases for Features in the Roadmap are automatically appended as an appendix in the PPT export. If you want a richer appendix, generate canvases for your key Features before running the export.</p><h3 id="use-ai-speaker-notes-as-a-starting-point" tabindex="-1">Use AI speaker notes as a starting point <a class="header-anchor" href="#use-ai-speaker-notes-as-a-starting-point" aria-label="Permalink to &quot;Use AI speaker notes as a starting point&quot;">​</a></h3><p>The AI-generated speaker notes give you a draft narrative for each slide, tuned to your chosen audience. They&#39;re designed as inspiration, not a script — edit them to reflect your specific context, priorities, and communication style.</p><h3 id="tune-audience-settings-to-the-room" tabindex="-1">Tune audience settings to the room <a class="header-anchor" href="#tune-audience-settings-to-the-room" aria-label="Permalink to &quot;Tune audience settings to the room&quot;">​</a></h3><p>The three audience options (Internal general, Internal executive, External) meaningfully change the tone and framing of the AI-generated content. Choosing the right one saves editing time.</p><hr><h2 id="roadmap-vs-release-when-to-use-each" tabindex="-1">Roadmap vs Release: When to Use Each <a class="header-anchor" href="#roadmap-vs-release-when-to-use-each" aria-label="Permalink to &quot;Roadmap vs Release: When to Use Each&quot;">​</a></h2><p>A question that comes up often: should I use a Roadmap or a Release to communicate with stakeholders?</p><table tabindex="0"><thead><tr><th>Use a Roadmap when...</th><th>Use a Release when...</th></tr></thead><tbody><tr><td>You&#39;re explaining priorities and strategic direction</td><td>You&#39;re reporting on progress and delivery status</td></tr><tr><td>The audience needs to understand WHAT and WHY</td><td>The audience needs to understand WHEN and HOW IT&#39;S GOING</td></tr><tr><td>You&#39;re presenting to leadership, sales, or customers</td><td>You&#39;re updating the team, CS, or ops on delivery</td></tr><tr><td>The plan is forward-looking</td><td>The view is current-state</td></tr></tbody></table><p>In practice, most PMs use both — a Roadmap sets the narrative, and a Release updates it over time.</p><hr><p><em>Next: Troubleshooting &amp; FAQs — common issues, drag-and-drop tips, and export troubleshooting.</em></p>',52)])])}const m=t(i,[["render",n]]);export{c as __pageData,m as default};
